    """Color each contiguous block of the turquoise silhouette from its marker key."""
    h, w = len(grid), len(grid[0])
    # Marker key: colors in the sparse key encode the large contiguous blocks.
    # The demonstrated patterns correspond to these blocks in row-major order.
    out = [row[:] for row in grid]
    # Detect turquoise regions. Each region is colored using the key's color
    # order (row-major marker cells); colors are repeated only where shapes span
    # more than one key cell.
    from collections import deque
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == 8:
