                        q.append((yy, xx))
            components.append(cells)
    # Regions can touch and form one component, so split the silhouette into
    # maximal solid rectangular blocks, as in the demonstrations.
    blocks = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 8:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 8:
                c += 1
            blocks.append((r, start, c))
